  "sids/Tel_Jeroen/Blond_Blubber.sid": "(#1)\nCOMMENT: Same as /MUSICIANS/T/Tel_Jeroen/Looking_Around.sid\n(#2)\n   NAME: 2 Channel Charm\n(#3)\n   NAME: 2 Channel Chock",
